'use strict';
const canvas=document.querySelector('#game'),$=s=>document.querySelector(s);
const colors=['#43edb1','#ffbb32','#34cfff','#ff386a'],names=['MOR','EMBER','VIOLET','GOLD'];
let joyAxis=0;
let mode='survival',round=1,totals=[0,0,0,0],history=[];
let players=[],balls=[],particles=[],state='ready',level=1,elapsed=0,spawnClock=0,acc=0,last=0,keys={},pointer=null,shake=0,sound=false,audio=null,toastTimer=0,hits=0;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function reset(){players=names.map((name,i)=>({name,i,p:450,v:0,score:0,hp:mode==='challenge'?(i===0?8:12):10,cd:0,pulse:0,target:450,think:0}));balls=[];particles=[];elapsed=0;spawnClock=0;hits=0;shake=0;pointer=null;joyAxis=0;keys={};toastTimer=0;$('#toast').textContent='';$('#time').textContent='00:00';$('#charge').style.width='100%';$('#charge').style.transform='scaleX(1)';$('#charge-label').textContent='READY';for(let i=0;i<3;i++)spawn(i*2.094+.4);updateUI();}
function spawn(angle=Math.random()*Math.PI*2){const speed=190;balls.push({x:450+Math.cos(angle)*25,y:450+Math.sin(angle)*25,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,r:9,trail:[],owner:-1,hot:0});}
function local(i,b){return i===0?{u:b.x,d:800-b.y,vu:b.vx,vd:-b.vy}:i===1?{u:b.x,d:b.y-100,vu:b.vx,vd:b.vy}:i===2?{u:b.y,d:b.x-100,vu:b.vy,vd:b.vx}:{u:b.y,d:800-b.x,vu:b.vy,vd:-b.vx};}
function world(i,u,d){return i===0?[u,800-d]:i===1?[u,100+d]:i===2?[100+d,u]:[800-d,u];}
function velocity(i,vu,vd,b){if(i<2){b.vx=vu;b.vy=i===0?-vd:vd;}else{b.vy=vu;b.vx=i===2?vd:-vd;}}
function place(i,u,d,b){[b.x,b.y]=world(i,u,d);}
function tone(freq=400,duration=.06,type='sine',volume=.06){if(!sound||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.45,audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
function burst(x,y,color,n=14){for(let k=0;k<n;k++){const a=Math.random()*Math.PI*2,s=60+Math.random()*230;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.3+Math.random()*.35,max:.65,color});}}
function notify(t){$('#toast').textContent=t;toastTimer=1.5;}
function blast(i){const p=players[i];if(state!=='playing'||!p.hp||p.cd>0)return;p.cd=1.35;p.pulse=.22;tone(180,.13,'triangle');}
function reflect(v){const lo=110,span=680;let t=((v-lo)%(span*2)+span*2)%(span*2);return lo+(t>span?span*2-t:t);}
function update(dt){if(state!=='playing')return;elapsed+=dt;spawnClock+=dt;const cap=level===2?6:level===1?5:4;if(spawnClock>16&&balls.length<cap){spawn();spawnClock=0;notify('NEW BALL IN PLAY');}
for(const p of players){p.cd=Math.max(0,p.cd-dt);p.pulse=Math.max(0,p.pulse-dt);if(!p.hp)continue;const old=p.p;if(p.i===0){let dir=joyAxis||((keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0));if(dir){pointer=null;p.v=dir*680;p.p+=p.v*dt;}else if(pointer!==null){p.p+=clamp(pointer-p.p,-780*dt,780*dt);}else{p.v=0;}}else{p.think-=dt;if(p.think<=0){let best=10,target=450;for(const b of balls){const l=local(p.i,b);if(l.vd<-15&&l.d>30){const t=(l.d-43)/-l.vd;if(t>=0&&t<best){best=t;target=reflect(l.u+l.vu*t);}}}p.target=target+(Math.random()-.5)*[95,48,20][level];p.think=[.2,.12,.07][level];}p.p+=clamp(p.target-p.p,-[270,365,460][level]*dt,[270,365,460][level]*dt);for(const b of balls){const l=local(p.i,b);if(l.vd<0&&l.d<110&&Math.abs(l.u-p.p)<65&&Math.random()<dt*5)blast(p.i);}}
p.p=clamp(p.p,264,636);if(p.i!==0||pointer!==null)p.v=(p.p-old)/dt;}
for(let j=balls.length-1;j>=0;j--){const b=balls[j];b.hot=Math.max(0,b.hot-dt);b.trail.push([b.x,b.y]);if(b.trail.length>13)b.trail.shift();b.x+=b.vx*dt;b.y+=b.vy*dt;let lost=false;for(let i=0;i<4;i++){const p=players[i],l=local(i,b);if(l.vd>=0)continue;const reach=p.pulse>0?83:44;
if(p.hp&&l.d<reach&&l.d>12&&Math.abs(l.u-p.p)<62){const offset=clamp((l.u-p.p)/62,-1,1),speed=Math.hypot(b.vx,b.vy)+(1200-Math.hypot(b.vx,b.vy))*(p.pulse>0?.13:.075);const angle=clamp(offset*.95+p.v*.0004,-1.13,1.13);velocity(i,Math.sin(angle)*speed,Math.cos(angle)*speed,b);place(i,l.u,reach+1,b);b.owner=i;b.hot=p.pulse>0?.5:.12;burst(b.x,b.y,colors[i],p.pulse>0?22:8);tone(p.pulse>0?500:330,.06);if(i===0)hits++;continue;}
if(l.d<b.r){if(!p.hp||l.u<210||l.u>690){place(i,l.u,b.r+1,b);velocity(i,l.vu,-l.vd,b);burst(b.x,b.y,'#8da59c',3);}else{lost=true;balls.splice(j,1);burst(b.x,b.y,colors[i],35);shake=i===0?9:4;tone(95,.23,'sawtooth',.045);goal(i,b.owner);if(state!=='playing')return;spawn();break;}}}if(lost)continue;}
for(let i=0;i<balls.length;i++)for(let j=i+1;j<balls.length;j++){const a=balls[i],b=balls[j],dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy);if(d>0&&d<18){const nx=dx/d,ny=dy/d,dot=(b.vx-a.vx)*nx+(b.vy-a.vy)*ny;if(dot<0){const sa=Math.hypot(a.vx,a.vy),sb=Math.hypot(b.vx,b.vy);a.vx+=dot*nx;a.vy+=dot*ny;b.vx-=dot*nx;b.vy-=dot*ny;const na=Math.hypot(a.vx,a.vy),nb=Math.hypot(b.vx,b.vy);if(na>1e-9){a.vx*=sa/na;a.vy*=sa/na;}else{a.vx=-nx*sa;a.vy=-ny*sa;}if(nb>1e-9){b.vx*=sb/nb;b.vy*=sb/nb;}else{b.vx=nx*sb;b.vy=ny*sb;}}const push=(18-d)/2+.1;a.x-=nx*push;a.y-=ny*push;b.x+=nx*push;b.y+=ny*push;}}
for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;}particles=particles.filter(p=>p.life>0);shake*=Math.exp(-15*dt);toastTimer-=dt;if(toastTimer<0&&$('#toast').textContent)$('#toast').textContent='';}
let hudClock=0;
function updateHUD(delta){hudClock+=delta;if(hudClock<.1)return;hudClock=0;$('#time').textContent=`${Math.floor(elapsed/60).toString().padStart(2,'0')}:${Math.floor(elapsed%60).toString().padStart(2,'0')}`;$('#charge').style.transform=`scaleX(${1-players[0].cd/1.35})`;$('#charge-label').textContent=players[0].cd>0?'CHARGING':'READY';$('#balls-count').textContent=balls.length+' ENERGY BALLS';}
function phase(){return mode==='tournament'?`ROUND ${round} / 3 · FIRST TO 10`:!players[0].hp?'ELIMINATED · SPECTATING':mode==='challenge'?'CHALLENGE · 8 VS 12':'SURVIVAL · LAST GUARD STANDING';}
function rules(){return mode==='tournament'?'First to 10 goals wins each round and banks 20.<br>Others bank their score. Highest total after 3 rounds wins.':mode==='challenge'?'You have 8 lives. Each rival has 12.<br>Last guard standing wins.': 'Ten lives each. No second chances.<br>Last guard standing wins.';}
function updateUI(){const tournament=mode==='tournament';$('#players').innerHTML=players.map(p=>{const max=mode==='challenge'?(p.i===0?8:12):10;return `<div class="player ${p.hp?'':'out'}" style="--c:${colors[p.i]}"><div class="avatar">${['M','E','V','G'][p.i]}</div><div><div class="player-name">${p.name}<small>${p.i===0?'YOU':'CPU'}</small></div>${tournament?`<div class="score-detail">ROUND ${p.score}/10 · BANKED ${totals[p.i]}</div>`:`<div class="lives">${Array.from({length:max},(_,i)=>`<i class="life ${i<p.hp?'':'off'}"></i>`).join('')}</div>`}</div><span class="life-number">${tournament?p.score:(p.hp||'OUT')}</span></div>`;}).join('');$('#rules').innerHTML=rules();$('#round-label').textContent=tournament?`ROUND ${round}/3`:'01—04';$('#mode-note').innerHTML=rules();$('#restart').textContent=tournament?'↻ RESTART TOURNAMENT':'↻ RESTART MATCH';}
function goal(conceder,owner){if(mode==='tournament'){if(owner>=0&&owner!==conceder){players[owner].score++;notify(names[owner]+' +1');updateUI();if(players[owner].score>=10)finishRound(owner);}return;}players[conceder].hp--;if(!players[conceder].hp){notify(conceder===0?'YOU ARE OUT · SPECTATING':names[conceder]+' ELIMINATED');$('#phase').textContent=phase();}updateUI();if(players.filter(p=>p.hp>0).length===1)finish();}
function scoreboard(){return `<table class="results"><thead><tr><th>PLAYER</th>${[1,2,3].map(r=>`<th>R${r}</th>`).join('')}<th>TOTAL</th></tr></thead><tbody>${players.slice().sort((a,b)=>totals[b.i]-totals[a.i]).map(p=>`<tr style="color:${colors[p.i]}"><th>${p.name}</th>${[0,1,2].map(r=>`<td>${history[r]?history[r][p.i]:'—'}</td>`).join('')}<td><b>${totals[p.i]}</b></td></tr>`).join('')}</tbody></table>`;}
function finishRound(winner){const points=players.map(p=>p.i===winner?20:p.score);history.push(points);points.forEach((v,i)=>totals[i]+=v);state=round===3?'ended':'roundEnd';updateUI();$('#phase').textContent=round===3?'TOURNAMENT COMPLETE':`ROUND ${round} COMPLETE`;let title=`${names[winner]} wins.`,tag=`ROUND ${round} / 3 · WINNER 10 × 2 = 20`;if(round===3){const highest=Math.max(...totals),winners=names.filter((_,i)=>totals[i]===highest);title=winners.length>1?'Shared victory.':`${winners[0]} wins it.`;tag=winners.length>1?winners.join(' + ')+' · TIED ON '+highest:'TOURNAMENT CHAMPION · '+highest+' POINTS';}overlay(tag,title,`<span>${names[winner]} banks 20. Everyone else keeps their round score.</span>${scoreboard()}`,round===3?'PLAY TOURNAMENT AGAIN':'NEXT ROUND');tone(winner===0?650:220,.3,'triangle');}
function prepare(){round=1;totals=[0,0,0,0];history=[];state='ready';reset();$('#phase').textContent='READY · '+(mode==='tournament'?'3-ROUND TOURNAMENT':mode.toUpperCase());overlay(mode==='tournament'?'THREE ROUNDS. ONE CHAMPION.':mode==='challenge'?'THE ODDS ARE AGAINST YOU':'THE ARENA IS YOURS',mode==='tournament'?'Chase the ten.':mode==='challenge'?'Beat the odds.':'Hold the line.',rules(),'ENTER ARENA');}
function overlay(tag,title,copy,button){$('#overlay-tag').textContent=tag;$('#overlay-title').textContent=title;$('#overlay-copy').innerHTML=copy;$('#start').innerHTML=button+' <span>↗</span>';$('#overlay').classList.remove('hidden');}
function finish(){state='ended';const winner=players.find(p=>p.hp>0),won=winner.i===0;$('#phase').textContent='MATCH COMPLETE';overlay('LAST GUARD STANDING',won?'Turf defended.':winner.name+' wins.',`${Math.floor(elapsed)} seconds · ${hits} returns<br>${won?'Your gate held. Everyone else folded.':'You can take the arena back.'}`,'PLAY AGAIN');tone(won?650:120,.4,'triangle');}
function start(){if(state==='paused'){state='playing';}else if(state==='roundEnd'){round++;reset();state='playing';}else{round=1;totals=[0,0,0,0];history=[];reset();state='playing';}$('#overlay').classList.add('hidden');$('#phase').textContent=phase();$('#pause').textContent='Ⅱ';acc=0;last=performance.now();if(audio)audio.resume();}
function pause(){if(state==='playing'){state='paused';keys={};$('#phase').textContent='MATCH PAUSED';$('#pause').textContent='▶';overlay('TAKE A BREATHER','Time out.','Your gate can wait.<br>Resume when you’re ready.','RESUME MATCH');}else if(state==='paused')start();}
function draw(){window.arena3D?.render({players,balls,particles,shake,state});}
let lastMeasured=0;
function frame(now){const delta=Math.min((now-last)/1000,.05);last=now;window.perfTracker?.frame(now-lastMeasured,state==='playing'&&!document.hidden);lastMeasured=now;if(state==='playing'){acc+=delta;while(acc>=1/120){update(1/120);acc-=1/120;if(state!=='playing'){acc=0;break;}}}updateHUD(delta);draw();requestAnimationFrame(frame);}
$('#start').onclick=start;$('#restart').onclick=()=>{prepare();start();};$('#pause').onclick=pause;$('#blast').addEventListener('pointerdown',e=>{e.preventDefault();blast(0);});
$('#sound').onclick=()=>{sound=!sound;if(sound&&!audio)audio=new (window.AudioContext||window.webkitAudioContext)();if(audio)audio.resume();$('#sound').textContent=sound?'SOUND ON':'SOUND OFF';$('#sound').setAttribute('aria-pressed',sound);tone(500);};
for(const button of document.querySelectorAll('[data-level]'))button.onclick=()=>{level=Number(button.dataset.level);document.querySelectorAll('[data-level]').forEach(b=>b.classList.toggle('selected',b===button));$('#level-note').textContent=['Forgiving rivals. Find your rhythm.','Quick rivals. Three opening balls.','Fast rivals. More balls. Maximum pressure.'][level];prepare();};
for(const button of document.querySelectorAll('[data-mode]'))button.onclick=()=>{mode=button.dataset.mode;document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',b===button);});prepare();};
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' ','Escape','a','d','p'].includes(e.key)){e.preventDefault();keys[e.key]=true;if(e.key===' '&&!e.repeat){if(state==='ready'||state==='ended'||state==='roundEnd')start();else blast(0);}if((e.key==='Escape'||e.key==='p')&&!e.repeat)pause();}});window.addEventListener('keyup',e=>keys[e.key]=false);window.addEventListener('blur',()=>{keys={};if(state==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pause();});
function point(e){pointer=window.arena3D?.pointer(e)??450;}
canvas.addEventListener('pointerdown',e=>{point(e);canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(e.buttons||e.pointerType==='touch')point(e);});canvas.addEventListener('pointerup',()=>{pointer=null;players[0].v=0;});canvas.addEventListener('pointercancel',()=>{pointer=null;players[0].v=0;});
const stick=$('#joystick'),knob=$('#stick-knob');let stickPointer=null;
function moveStick(e){if(e.pointerId!==stickPointer)return;const r=stick.getBoundingClientRect(),limit=r.width*.32;const x=clamp(e.clientX-r.left-r.width/2,-limit,limit),axis=x/limit,dead=.06;joyAxis=Math.abs(axis)<=dead?0:Math.sign(axis)*Math.pow((Math.abs(axis)-dead)/(1-dead),1.25);knob.style.transform=`translate(${x}px,0px)`;stick.setAttribute('aria-valuenow',Math.round(joyAxis*100));}
function releaseStick(e){if(e?.pointerId!==undefined&&e.pointerId!==stickPointer)return;joyAxis=0;if(players[0])players[0].v=0;stickPointer=null;knob.style.transform='translate(0,0)';stick.setAttribute('aria-valuenow','0');}
stick.addEventListener('pointerdown',e=>{if(stickPointer!==null)return;e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);pointer=null;moveStick(e);});stick.addEventListener('pointermove',moveStick);for(const type of ['pointerup','pointercancel','lostpointercapture'])stick.addEventListener(type,releaseStick);window.addEventListener('blur',releaseStick);
const panel=$('#settings-panel');function showSettings(){if(state==='playing')pause();releaseStick();panel.hidden=false;$('#settings').setAttribute('aria-expanded','true');}function closeSettings(){panel.hidden=true;$('#settings').setAttribute('aria-expanded','false');}
$('#settings').onclick=showSettings;$('#close-settings').onclick=closeSettings;$('#done-settings').onclick=closeSettings;
let effects=false;$('#quality').onclick=()=>{effects=!effects;window.arena3D?.setQuality(effects);$('#quality').setAttribute('aria-pressed',effects);};
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement){await document.exitFullscreen();}else if($('#app').requestFullscreen){await $('#app').requestFullscreen();}else{notify('ADD TO HOME SCREEN FOR MORE SPACE');}}catch{notify('FULLSCREEN UNAVAILABLE · BOTH ORIENTATIONS SUPPORTED');}};
$('#start').disabled=false;
prepare();requestAnimationFrame(frame);
